import { t as logLine } from "../../../../chunks/log.js";
import { r as usesFixtureHistory, t as listFixtureSamples } from "../../../../chunks/fixtures.js";
//#region src/routes/admin/scrap-tickets/+page.server.js
async function load() {
	const fixtureMode = usesFixtureHistory();
	if (!fixtureMode) return {
		fixtureMode,
		samples: []
	};
	try {
		return {
			fixtureMode,
			samples: await listFixtureSamples()
		};
	} catch (error) {
		console.error(logLine("scrap", "muestras no leidas", { source: "fixture" }), error);
		return {
			fixtureMode,
			samples: [],
			error: "Sample histories could not be read."
		};
	}
}
//#endregion
export { load };
